package rentivo_backend.repository; import org.springframework.data.jpa.repository.JpaRepository; import rentivo_backend.entity.Listing; import java.util.*;
public interface ListingRepository extends JpaRepository<Listing,Long>{ List<Listing> findByOwnerIdAndStatusNot(Long ownerId, Listing.Status status); List<Listing> findByStatusOrderByCreatedAtDesc(Listing.Status status); long countByStatus(Listing.Status status); }
